contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable {
        require(true);
        // We do not call c.deposit so this contract should have zero recorded credit in c.
        uint beforeCBalance = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterCBalance = address(c).balance;
        // General rule: if we never deposited (so recorded credit is zero), withdrawAll cannot decrease C's balance.
        // Expressed solely via observable balances and the revert flag.
        assert(afterCBalance >= beforeCBalance);
    }
    receive() external payable { }
}

